{"hypotheses": [
  {
    "name": "Asset Growth Defensive Value",
    "mechanism": "Combining AssetGrowth (which penalizes high asset growth) with BM (value) and Beta (market risk) may capture periods where value signals are robust but are contaminated by growth-related risk. By subtracting Beta, the composite isolates value and anti-growth effects uncorrelated with market beta, producing a defensive value factor that should outperform during market stress.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -1.0, "primitive": "Beta"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 42
  },
  {
    "name": "Intangible Quality Momentum",
    "mechanism": "Firms with strong analyst value (consensus optimism), high gross profitability, and high intangible intensity (IntanBM) may capture persistent momentum as the market underappreciates quality intangible investment. The combination targets stocks where positive analyst sentiment is supported by real, intangible-driven profitability.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "AnalystValue"},
        {"weight": 1.0, "primitive": "GP"},
        {"weight": 0.5, "primitive": "IntanBM"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 1.08,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Volatility-Managed Reversal",
    "mechanism": "Combining STreversal (short-term reversal) and MRreversal (medium-run reversal), but only activating when volatility (RealizedVol) is high, captures the tendency for reversal profits to be concentrated in turbulent markets, as liquidity- and risk-driven mispricings revert.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "STreversal"},
        {"weight": 1.0, "primitive": "MRreversal"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.82,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Dispersed Ownership Quality",
    "mechanism": "Combining DelBreadth (ownership breadth), GP (gross profitability), and subtracting BidAskSpread (illiquidity) captures high-quality, widely-held stocks with lower liquidity risk. These stocks should exhibit more persistent returns due to broader investor attention and lower trading costs.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelBreadth"},
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 1.10,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Defensive Earnings Momentum",
    "mechanism": "EarningsSurprise and AnalystRevision are classic earnings momentum signals. Subtracting BetaTailRisk isolates stocks where earnings momentum is not simply compensated for bearing tail risk, creating a defensive version likely to persist when overall market beta risk is not rewarded.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "AnalystRevision"},
        {"weight": -1.0, "primitive": "BetaTailRisk"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.93,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Financing-Driven Contrarian",
    "mechanism": "Combining ShareIss1Y (share issuance), DebtIssuance, and LRreversal (long-run reversal) with negative weights on the issuance factors exploits the tendency for firms conducting financing activities to underperform, especially after prior price run-ups. This composite should exploit overvaluation from both equity and debt financing waves.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "ShareIss1Y"},
        {"weight": -0.5, "primitive": "DebtIssuance"},
        {"weight": 1.0, "primitive": "LRreversal"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.87,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Seasonal Quality Reversal",
    "mechanism": "This composite combines off-season reversal (MomOffSeason), Piotroski F-score (PS), and CashProd (cash productivity) to isolate mean reversion in high-quality firms. It bets on reversals being more predictable in firms with robust fundamental profiles, rather than junk firms.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomOffSeason"},
        {"weight": 0.5, "primitive": "PS"},
        {"weight": 0.5, "primitive": "CashProd"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "MomOffSeason", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Liquidity-Filtered Momentum",
    "mechanism": "By combining Mom12m (momentum), subtracting Illiquidity, and adding VolumeTrend, this composite targets stocks with strong momentum signals but filters out illiquid names and weights toward those experiencing persistent volume increases, reducing implementation costs and focusing on robust trends.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "VolumeTrend"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.05,
    "expected_decay_half_life_months": 20
  }
]}
